routerAdd('GET','/api/pfriends/forum/channels',(e)=>{const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e);return e.json(200,{items:e.app.findRecordsByFilter('forum_channels','active=true','position',0,0).filter(x=>u.canRead(e.app,user,x)).map(x=>u.channelDto(e.app,x,user))})},$apis.requireAuth('users'));
routerAdd('GET','/api/pfriends/forum/channels/{slug}/messages',(e)=>{const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e),channel=e.app.findFirstRecordByData('forum_channels','slug',e.request.pathValue('slug'));if(!u.canRead(e.app,user,channel))throw new ForbiddenError('Kanal tidak dapat diakses.');const before=e.request.url.query().get('before')||'',limit=Math.min(50,Math.max(1,Number(e.request.url.query().get('perPage')||50)));const filter=before?'channel={:c} && sentAt<{:before}':'channel={:c}',params=before?{c:channel.id,before}:{c:channel.id};const rows=e.app.findRecordsByFilter('forum_messages',filter,'-sentAt',limit+1,0,params),hasMore=rows.length>limit;return e.json(200,{items:rows.slice(0,limit).reverse().map(x=>u.messageDto(e.app,x,user.id)),hasMore,nextCursor:hasMore?rows[limit-1].getString('sentAt'):''})},$apis.requireAuth('users'));
routerAdd('GET','/api/pfriends/forum/messages/{id}/context',(e)=>{const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e),target=e.app.findRecordById('forum_messages',e.request.pathValue('id')),channel=e.app.findRecordById('forum_channels',target.getString('channel'));if(!u.canRead(e.app,user,channel))throw new ForbiddenError('Pesan tidak dapat diakses.');const at=target.getString('sentAt'),params={c:channel.id,at},before=e.app.findRecordsByFilter('forum_messages','channel={:c} && sentAt<{:at}','-sentAt',20,0,params).reverse(),after=e.app.findRecordsByFilter('forum_messages','channel={:c} && sentAt>{:at}','sentAt',20,0,params);return e.json(200,{channelSlug:channel.getString('slug'),items:[...before,target,...after].map(x=>u.messageDto(e.app,x,user.id))})},$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/forum/channels/{slug}/messages',(e)=>{const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e),channel=e.app.findFirstRecordByData('forum_channels','slug',e.request.pathValue('slug'));if(!u.canWrite(e.app,user,channel))throw new ForbiddenError('Anda tidak dapat menulis di kanal ini.');const body=new DynamicModel({content:'',requestKey:'',replyTo:''});e.bindBody(body);const content=String(body.content||'').trim(),replyTo=String(body.replyTo||'').trim();if(!content||content.length>600)throw new BadRequestError('Pesan wajib berisi 1 sampai 600 karakter.');if(!String(body.requestKey||'').trim())throw new BadRequestError('requestKey wajib diisi.');let parent=null;if(replyTo){parent=e.app.findRecordById('forum_messages',replyTo);if(parent.getString('channel')!==channel.id)throw new BadRequestError('Pesan balasan harus berada di kanal yang sama.')}let row;try{row=e.app.findFirstRecordByFilter('forum_messages','author={:a} && requestKey={:k}',{a:user.id,k:body.requestKey})}catch(_){const recent=e.app.findRecordsByFilter('forum_messages','author={:a} && sentAt>{:since}','-sentAt',20,0,{a:user.id,since:new Date(Date.now()-60000).toISOString().replace('T',' ')});if(recent.length>=10)throw new TooManyRequestsError('Terlalu banyak pesan. Coba lagi sebentar.');const who=u.identity(e.app,user);row=new Record(e.app.findCollectionByNameOrId('forum_messages'));for(const [key,value] of Object.entries({channel:channel.id,author:user.id,authorKind:'USER',authorName:who.name,authorLabel:who.label,content,requestKey:String(body.requestKey),replyTo:parent?parent.id:'',sentAt:new Date().toISOString()}))row.set(key,value);e.app.save(row);u.publish(e.app,`forum:channel:${channel.id}`,{type:'message.created',message:u.messageDto(e.app,row,user.id)})}return e.json(201,u.messageDto(e.app,row,user.id))},$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/forum/messages/{id}/reaction',(e)=>{const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e),message=e.app.findRecordById('forum_messages',e.request.pathValue('id')),channel=e.app.findRecordById('forum_channels',message.getString('channel'));if(!u.canRead(e.app,user,channel))throw new ForbiddenError('Pesan tidak dapat diakses.');const body=new DynamicModel({emoji:'',selected:false});e.bindBody(body);if(!u.EMOJIS.includes(String(body.emoji)))throw new BadRequestError('Reaksi tidak didukung.');let row=null;try{row=e.app.findFirstRecordByFilter('forum_reactions','message={:m} && user={:u} && emoji={:e}',{m:message.id,u:user.id,e:body.emoji})}catch(_){}if(body.selected&&!row){row=new Record(e.app.findCollectionByNameOrId('forum_reactions'));row.set('message',message.id);row.set('user',user.id);row.set('emoji',body.emoji);e.app.save(row)}else if(!body.selected&&row)e.app.delete(row);const dto=u.messageDto(e.app,message,user.id);u.publish(e.app,`forum:channel:${channel.id}`,{type:'message.reactions',messageId:message.id,reactions:dto.reactions.map(x=>({emoji:x.emoji,count:x.count}))});return e.json(200,{reactions:dto.reactions})},$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/forum/presence/heartbeat',(e)=>{const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e),body=new DynamicModel({channel:''});e.bindBody(body);let channel=null;if(body.channel){channel=e.app.findFirstRecordByData('forum_channels','slug',body.channel);if(!u.canRead(e.app,user,channel))throw new ForbiddenError('Kanal tidak dapat diakses.')}let row;try{row=e.app.findFirstRecordByData('forum_presences','user',user.id)}catch(_){row=new Record(e.app.findCollectionByNameOrId('forum_presences'));row.set('user',user.id)}row.set('channel',channel?channel.id:'');row.set('lastSeenAt',new Date().toISOString());e.app.save(row);u.publish(e.app,'forum:presence',{type:'presence.changed'});return e.noContent(204)},$apis.requireAuth('users'));
routerAdd('GET','/api/pfriends/forum/presence',(e)=>{const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e),now=Date.now(),cutoff=new Date(now-300000).toISOString().replace('T',' ');return e.json(200,{items:e.app.findRecordsByFilter('forum_presences','lastSeenAt>={:cutoff}','-lastSeenAt',50,0,{cutoff}).map(row=>{const target=e.app.findRecordById('users',row.getString('user')),who=u.identity(e.app,target),age=now-new Date(row.getString('lastSeenAt')).getTime();return{id:target.id,name:who.name,label:who.label,state:age<=90000?'aktif':'sibuk'}})})},$apis.requireAuth('users'));
onRealtimeSubscribeRequest((e)=>{for(const topic of e.subscriptions){if(!String(topic).startsWith('forum:'))continue;const u=require(`${__hooks}/forum-utils.js`),user=u.auth(e);if(topic==='forum:presence')continue;const prefix='forum:channel:';if(!topic.startsWith(prefix))throw new ForbiddenError('Topik Forum tidak dikenal.');const channel=e.app.findRecordById('forum_channels',topic.slice(prefix.length));if(!u.canRead(e.app,user,channel))throw new ForbiddenError('Kanal tidak dapat diakses.')}return e.next()});
